import{sankey,sankeyLinkHorizontal}from'../upstream/src/index.js';import'./style.css';
const NS='http://www.w3.org/2000/svg',root=document.getElementById('root');root.innerHTML=`<main><header><small>D3 SANKEY · 工作流分配图</small><h1>看见信息如何流向结果。</h1><p>虚构的 100 单位工作量，用真实桑基图引擎计算带宽。不是模型调用、成本账单或实时数据。</p></header><nav><label>分配给分析 <input type="range" id="weight" min="10" max="90" step="5" value="60"><output id="weight-label">60%</output></label><button id="reset">恢复分配</button><button id="clear">取消高亮</button></nav><section><svg id="chart" viewBox="0 0 900 470" role="img" aria-label="本地工作流桑基图"></svg></section><footer><span id="readout" aria-live="polite">点击节点聚焦路径；拖动节点或使用上下方向键调整位置。</span><button id="table-toggle">查看数值表</button></footer><table hidden id="table"><thead><tr><th>来源</th><th>去向</th><th>工作量</th></tr></thead><tbody></tbody></table></main>`;
const names=['资料阅读','讨论记录','分析 Agent','撰写 Agent','证据摘要','交付草稿'],colors=['#829d8d','#b8a086','#749493','#b28d9b','#78986e','#ab9677'];let graph,engine,selected=null,drag=null;const svg=document.getElementById('chart');const link=sankeyLinkHorizontal();const el=(name,attrs={},text)=>{const x=document.createElementNS(NS,name);for(const[k,v]of Object.entries(attrs))x.setAttribute(k,String(v));if(text!==undefined)x.textContent=text;return x};
function data(){const p=+document.getElementById('weight').value;return{nodes:names.map((name,id)=>({id,name})),links:[{source:0,target:2,value:p*.6},{source:1,target:2,value:p*.4},{source:0,target:3,value:(100-p)*.6},{source:1,target:3,value:(100-p)*.4},{source:2,target:4,value:p*.75},{source:2,target:5,value:p*.25},{source:3,target:4,value:(100-p)*.15},{source:3,target:5,value:(100-p)*.85}]}}
function draw(){svg.replaceChildren();const defs=el('defs');svg.append(defs);graph.links.forEach((l,i)=>{const grad=el('linearGradient',{id:'flow-'+i,gradientUnits:'userSpaceOnUse',x1:l.source.x1,x2:l.target.x0});grad.append(el('stop',{offset:'0%','stop-color':colors[l.source.id]}),el('stop',{offset:'100%','stop-color':colors[l.target.id]}));defs.append(grad);const path=el('path',{d:link(l),fill:'none',stroke:'url(#flow-'+i+')','stroke-width':Math.max(1,l.width),'stroke-opacity':selected===null||l.source.id===selected||l.target.id===selected?.56:.09,'data-flow':i});path.append(el('title',{},`${l.source.name} → ${l.target.name}：${l.value.toFixed(1)} 单位`));svg.append(path)});graph.nodes.forEach(n=>{const g=el('g',{tabindex:0,role:'button','aria-label':`${n.name}，${n.value.toFixed(1)} 单位，点击聚焦，方向键移动`,'data-node':n.id,'aria-pressed':selected===n.id});const rect=el('rect',{x:n.x0,y:n.y0,width:n.x1-n.x0,height:n.y1-n.y0,rx:8,fill:colors[n.id],stroke:selected===n.id?'#30463a':'transparent','stroke-width':3});const left=n.x0>700;const text=el('text',{x:left?n.x0-12:n.x1+12,y:n.y0-10,'text-anchor':left?'end':'start',fill:'#34483b','font-size':13,'font-weight':600},n.name+' · '+n.value.toFixed(0));g.append(rect,text);g.addEventListener('click',()=>{selected=selected===n.id?null:n.id;draw();document.getElementById('readout').textContent=selected===null?'已取消高亮。':`${n.name}：${n.value.toFixed(1)} 单位`});g.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();move(n,n.y0+(e.key==='ArrowUp'?-12:12));svg.querySelector(`[data-node="${n.id}"]`).focus()}if(e.key==='Enter'||e.key===' '){e.preventDefault();g.dispatchEvent(new MouseEvent('click'))}});g.addEventListener('pointerdown',e=>{drag={id:n.id,y:point(e),start:n.y0};svg.setPointerCapture?.(e.pointerId)});svg.append(g)});const tbody=document.querySelector('tbody');tbody.replaceChildren();graph.links.forEach(l=>{const tr=document.createElement('tr');[l.source.name,l.target.name,l.value.toFixed(1)].forEach(t=>{const td=document.createElement('td');td.textContent=t;tr.append(td)});tbody.append(tr)})}
function point(e){const r=svg.getBoundingClientRect();return(e.clientY-r.top)*470/(r.height||470)}function move(n,y){const h=n.y1-n.y0;n.y0=Math.max(35,Math.min(440-h,y));n.y1=n.y0+h;engine.update(graph);draw()}
function rebuild(){engine=sankey().nodeId(d=>d.id).nodeWidth(18).nodePadding(52).extent([[40,35],[860,440]]);graph=engine(data());document.getElementById('weight-label').textContent=document.getElementById('weight').value+'%';draw()}
svg.addEventListener('pointermove',e=>{if(drag){const n=graph.nodes.find(n=>n.id===drag.id);move(n,drag.start+point(e)-drag.y)}});const release=()=>{drag=null};svg.addEventListener('pointerup',release);svg.addEventListener('pointercancel',release);document.getElementById('weight').addEventListener('input',rebuild);document.getElementById('reset').onclick=()=>{document.getElementById('weight').value=60;selected=null;rebuild()};document.getElementById('clear').onclick=()=>{selected=null;draw()};document.getElementById('table-toggle').onclick=()=>{document.getElementById('table').hidden=!document.getElementById('table').hidden};window.addEventListener('pagehide',()=>{drag=null;root.replaceChildren()},{once:true});rebuild();
